SELECT identity_tenant_id FROM tianquan_oauth.oauth_subject_tenant_history
 WHERE tenant_id = #{tenantId} AND identity_sub = #{subject} AND identity_tenant_id > #{after}
   AND deleted_at IS NULL ORDER BY identity_tenant_id LIMIT #{limit}

mapper.update:
UPDATE tianquan_oauth.oauth_security_state s
   SET version = s.version + 1, update_user_id = #{actor}, update_time = #{now}
 WHERE s.tenant_id = #{tenantId} AND s.id = #{id} AND s.version = #{expectedVersion}
   AND s.target_type = 'REALM' AND s.target_key = 'self' AND s.deleted_at IS NULL


        AND (SELECT count(*) FROM tianquan_oauth.oauth_subject_tenant_history h
             WHERE h.tenant_id = #{tenantId} AND h.identity_sub = #{subject}
               AND h.identity_tenant_id > #{after} AND h.identity_tenant_id <= #{last}
               AND h.deleted_at IS NULL) = #{count}

            AND EXISTS (SELECT 1 FROM tianquan_oauth.oauth_subject_tenant_history h
                WHERE h.tenant_id = #{tenantId} AND h.identity_sub = #{subject}
                  AND h.identity_tenant_id = #{tenant} AND h.deleted_at IS NULL)



        AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_subject_tenant_history h
            WHERE h.tenant_id = #{tenantId} AND h.identity_sub = #{subject}
              AND h.identity_tenant_id > #{after} AND h.deleted_at IS NULL)

UPDATE tianquan_oauth.oauth_subject_revocation_task
   SET status = 'DONE', lease_owner = NULL, lease_until = NULL, version = version + 1,
       update_user_id = #{actor}, update_time = #{now}
 WHERE tenant_id = #{tenantId} AND id = #{task.id} AND version = #{task.version}
   AND status = 'LEASED' AND lease_owner = #{owner} AND deleted_at IS NULL

UPDATE tianquan_oauth.oauth_subject_revocation_task
   SET status = 'PENDING', lease_owner = NULL, lease_until = NULL, next_attempt_at = #{next},
       version = version + 1, update_user_id = #{actor}, update_time = #{now}
 WHERE tenant_id = #{tenantId} AND id = #{task.id} AND version = #{task.version}
   AND status = 'LEASED' AND lease_owner = #{owner} AND deleted_at IS NULL
